/**
 * Site knowledge for the chat assistant.
 *
 * Three sources, all bundled into the function at deploy time:
 *  - site-pages.json: text of every prerendered page, split into sections
 *    (generated by scripts/build-chat-knowledge.mjs)
 *  - the FAQ list (src/data/faqs.ts)
 *  - the resource directory (src/data/directorySeed.ts)
 *
 * Search is a small in-memory BM25 index: the corpus is a few hundred KB, so
 * there is no need for embeddings or an external vector store.
 */

import sitePages from './site-pages.json';
import { faqs } from '../../src/data/faqs';
import { directorySeedData } from '../../src/data/directorySeed';
import type { Resource } from '../../src/types';

interface PageSection {
  heading: string;
  text: string;
}

interface SitePage {
  path: string;
  title: string;
  description: string;
  sections: PageSection[];
}

interface Doc {
  path: string;
  pageTitle: string;
  heading: string;
  text: string;
  tokens: string[];
}

const pages = (sitePages as { pages: SitePage[] }).pages;

const STOPWORDS = new Set(
  'a an and are as at be but by can do does for from has have how i if in into is it its me my of on or our so than that the their them then there these they this to was we what when where which who why will with you your'.split(
    ' ',
  ),
);

function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .split(/\s+/)
    .filter((t) => t.length > 1 && !STOPWORDS.has(t))
    .map(stem);
}

/** Very light stemming so "magnifiers" matches "magnifier" and "glasses" matches "glass". */
function stem(t: string): string {
  if (t.length > 4 && t.endsWith('ies')) return t.slice(0, -3) + 'y';
  if (t.length > 4 && t.endsWith('ing')) return t.slice(0, -3);
  if (t.length > 3 && t.endsWith('es') && /(ss|x|ch|sh)es$/.test(t)) return t.slice(0, -2);
  if (t.length > 3 && t.endsWith('s') && !t.endsWith('ss')) return t.slice(0, -1);
  return t;
}

const docs: Doc[] = [];

for (const page of pages) {
  for (const s of page.sections) {
    // The breadcrumb-only section adds noise without content.
    if (/^Home \(\/\)/.test(s.text) && s.text.length < 200) continue;
    docs.push({
      path: page.path,
      pageTitle: page.title,
      heading: s.heading,
      text: s.text,
      tokens: tokenize(`${page.title} ${s.heading} ${s.heading} ${s.text}`),
    });
  }
}

for (const f of faqs) {
  docs.push({
    path: '/faq',
    pageTitle: 'Frequently Asked Questions',
    heading: f.question,
    text: `Q: ${f.question}\nA: ${f.answer}`,
    tokens: tokenize(`${f.question} ${f.question} ${f.answer}`),
  });
}

// BM25 statistics
const K1 = 1.4;
const B = 0.75;
const docFreq = new Map<string, number>();
let totalLen = 0;
for (const d of docs) {
  totalLen += d.tokens.length;
  for (const t of new Set(d.tokens)) docFreq.set(t, (docFreq.get(t) ?? 0) + 1);
}
const avgLen = totalLen / Math.max(docs.length, 1);

function bm25(queryTokens: string[], tokens: string[], df: Map<string, number>, n: number, avg: number): number {
  if (tokens.length === 0) return 0;
  const tf = new Map<string, number>();
  for (const t of tokens) tf.set(t, (tf.get(t) ?? 0) + 1);
  let score = 0;
  for (const q of new Set(queryTokens)) {
    const f = tf.get(q);
    if (!f) continue;
    const nq = df.get(q) ?? 0;
    const idf = Math.log(1 + (n - nq + 0.5) / (nq + 0.5));
    score += idf * ((f * (K1 + 1)) / (f + K1 * (1 - B + (B * tokens.length) / avg)));
  }
  return score;
}

export function searchSite(query: string, limit = 6): string {
  const q = tokenize(query);
  if (q.length === 0) return 'The search query had no searchable words. Try different keywords.';

  const scored = docs
    .map((d) => ({ d, score: bm25(q, d.tokens, docFreq, docs.length, avgLen) }))
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score);

  // Keep at most two sections per page so one long page cannot crowd out the rest.
  const perPage = new Map<string, number>();
  const hits: Doc[] = [];
  for (const { d } of scored) {
    const n = perPage.get(d.path) ?? 0;
    if (n >= 2) continue;
    perPage.set(d.path, n + 1);
    hits.push(d);
    if (hits.length >= limit) break;
  }

  if (hits.length === 0) {
    return `No site content matched "${query}". Try other keywords, check the site map in your instructions, or use web search for outside sources.`;
  }

  return hits
    .map(
      (d, i) =>
        `[${i + 1}] Page: "${d.pageTitle}" (${d.path})\nSection: ${d.heading}\n${truncate(d.text, 1800)}`,
    )
    .join('\n\n---\n\n');
}

export function getPage(path: string): string {
  const clean = normalizePath(path);
  const page = pages.find((p) => p.path === clean);
  if (!page) {
    const close = pages
      .filter((p) => p.path.includes(clean.split('/').filter(Boolean).pop() ?? '###'))
      .map((p) => p.path)
      .slice(0, 5);
    return `No page found at "${clean}".${close.length ? ` Similar paths: ${close.join(', ')}` : ''}`;
  }
  const body = page.sections.map((s) => `## ${s.heading}\n${s.text}`).join('\n\n');
  return `# ${page.title} (${page.path})\n${page.description}\n\n${truncate(body, 24000)}`;
}

function normalizePath(path: string): string {
  let p = path.trim();
  try {
    if (/^https?:\/\//i.test(p)) p = new URL(p).pathname;
  } catch {
    /* keep as-is */
  }
  p = p.split(/[?#]/)[0];
  if (!p.startsWith('/')) p = `/${p}`;
  if (p.length > 1) p = p.replace(/\/+$/, '');
  return p;
}

// ── Resource directory ────────────────────────────────────────────────────

const STATE_NAMES: Record<string, string> = {
  AL: 'Alabama', AK: 'Alaska', AZ: 'Arizona', AR: 'Arkansas', CA: 'California', CO: 'Colorado',
  CT: 'Connecticut', DE: 'Delaware', DC: 'District of Columbia', FL: 'Florida', GA: 'Georgia',
  HI: 'Hawaii', ID: 'Idaho', IL: 'Illinois', IN: 'Indiana', IA: 'Iowa', KS: 'Kansas', KY: 'Kentucky',
  LA: 'Louisiana', ME: 'Maine', MD: 'Maryland', MA: 'Massachusetts', MI: 'Michigan', MN: 'Minnesota',
  MS: 'Mississippi', MO: 'Missouri', MT: 'Montana', NE: 'Nebraska', NV: 'Nevada', NH: 'New Hampshire',
  NJ: 'New Jersey', NM: 'New Mexico', NY: 'New York', NC: 'North Carolina', ND: 'North Dakota',
  OH: 'Ohio', OK: 'Oklahoma', OR: 'Oregon', PA: 'Pennsylvania', RI: 'Rhode Island', SC: 'South Carolina',
  SD: 'South Dakota', TN: 'Tennessee', TX: 'Texas', UT: 'Utah', VT: 'Vermont', VA: 'Virginia',
  WA: 'Washington', WV: 'West Virginia', WI: 'Wisconsin', WY: 'Wyoming', PR: 'Puerto Rico',
  ON: 'Ontario', QC: 'Quebec', BC: 'British Columbia', AB: 'Alberta', MB: 'Manitoba',
  SK: 'Saskatchewan', NS: 'Nova Scotia', NB: 'New Brunswick', NL: 'Newfoundland and Labrador',
  PE: 'Prince Edward Island',
};

function resourceText(r: Resource): string {
  return [
    r.organizationName,
    r.serviceTypes.join(' '),
    r.audienceTypes.join(' '),
    r.tags.join(' '),
    r.city,
    r.state ? STATE_NAMES[r.state] : '',
    r.country === 'US' || r.country === 'CA' ? STATE_NAMES[r.jurisdiction] ?? '' : '',
    r.jurisdiction === 'US' ? 'national nationwide' : '',
    r.sourceType,
    r.virtualAvailable ? 'virtual telehealth remote online' : '',
    r.insuranceNotes,
    r.costNotes,
  ]
    .filter(Boolean)
    .join(' ');
}

const resourceDocs = directorySeedData.map((r) => ({ r, tokens: tokenize(resourceText(r)) }));
const resDocFreq = new Map<string, number>();
let resTotal = 0;
for (const d of resourceDocs) {
  resTotal += d.tokens.length;
  for (const t of new Set(d.tokens)) resDocFreq.set(t, (resDocFreq.get(t) ?? 0) + 1);
}
const resAvg = resTotal / Math.max(resourceDocs.length, 1);

export interface DirectoryQuery {
  location?: string;
  service?: string;
  keywords?: string;
  virtual_only?: boolean;
}

const countryNames = new Intl.DisplayNames(['en'], { type: 'region' });

function countryName(code: string): string {
  try {
    return countryNames.of(code) ?? code;
  } catch {
    return code;
  }
}

/**
 * Location keys for a directory entry. US/Canadian entries use state/province
 * codes as their jurisdiction, while international entries use ISO country
 * codes, which collide (CA = California or Canada, DE = Delaware or Germany).
 * Two-letter input is therefore only matched against US/Canadian
 * jurisdictions, and countries are matched by name.
 */
function locationKeys(r: Resource): { codes: string[]; names: string[] } {
  const northAmerica = r.country === 'US' || r.country === 'CA';
  const codes = northAmerica ? [r.jurisdiction, r.state].filter((v): v is string => !!v) : [];
  const names = [
    northAmerica ? STATE_NAMES[r.jurisdiction] : undefined,
    r.state ? STATE_NAMES[r.state] : undefined,
    r.city,
    r.zip,
    countryName(r.country),
    r.country === 'US' ? 'United States' : undefined,
    r.country === 'US' ? 'USA' : undefined,
  ].filter((v): v is string => !!v);
  return { codes: codes.map((c) => c.toLowerCase()), names: names.map((n) => n.toLowerCase()) };
}

function matchesLocation(r: Resource, location: string): boolean {
  const loc = location.trim().toLowerCase().replace(/\.$/, '');
  if (!loc) return true;
  const { codes, names } = locationKeys(r);
  if (loc.length === 2) return codes.includes(loc);
  return names.some((n) => n === loc || (loc.length > 3 && n.length > 3 && (n.includes(loc) || loc.includes(n))));
}

export function searchDirectory(query: DirectoryQuery, limit = 8): string {
  let pool = resourceDocs;
  if (query.location) {
    const located = pool.filter((d) => matchesLocation(d.r, query.location!));
    pool = located;
  }
  if (query.virtual_only) pool = pool.filter((d) => d.r.virtualAvailable);

  const q = tokenize(`${query.service ?? ''} ${query.keywords ?? ''}`);
  const ranked = q.length
    ? pool
        .map((d) => ({ d, score: bm25(q, d.tokens, resDocFreq, resourceDocs.length, resAvg) }))
        .filter((x) => x.score > 0)
        .sort((a, b) => b.score - a.score)
        .map((x) => x.d)
    : pool;

  const nationwide = query.location
    ? resourceDocs.filter((d) => d.r.jurisdiction === 'US' && d.r.virtualAvailable)
    : [];

  const results = ranked.slice(0, limit).map((d) => d.r);
  if (results.length === 0) {
    const where = query.location ? ` in "${query.location}"` : '';
    const fallback = nationwide.slice(0, 4).map((d) => formatResource(d.r)).join('\n\n');
    return (
      `No directory entries matched${where}. The directory is not exhaustive — suggest the state/provincial blind services agency, ` +
      `the Find Local Resources page (/resources), or use web search for that area.` +
      (fallback ? `\n\nNationwide/virtual options:\n\n${fallback}` : '')
    );
  }

  return (
    `${results.length} of ${ranked.length} matching directory entries` +
    ` (the full list can be browsed at /resources):\n\n` +
    results.map(formatResource).join('\n\n')
  );
}

function formatResource(r: Resource): string {
  const lines = [
    `- ${r.organizationName}`,
    `  Location: ${[r.city, r.country === 'US' || r.country === 'CA' ? (r.jurisdiction === 'US' ? 'Nationwide' : STATE_NAMES[r.jurisdiction] ?? r.jurisdiction) : undefined, countryName(r.country)].filter(Boolean).join(', ')}`,
    `  Services: ${r.serviceTypes.join(', ')}`,
    `  Serves: ${r.audienceTypes.join(', ')}`,
  ];
  if (r.phone) lines.push(`  Phone: ${r.phone}`);
  if (r.website) lines.push(`  Website: ${r.website}`);
  if (r.address) lines.push(`  Address: ${r.address}`);
  lines.push(`  Virtual services: ${r.virtualAvailable ? 'yes' : 'no'}; Referral required: ${r.referralRequired ? 'yes' : 'no'}`);
  if (r.insuranceNotes) lines.push(`  Insurance: ${r.insuranceNotes}`);
  if (r.costNotes) lines.push(`  Cost: ${r.costNotes}`);
  if (r.availabilityNotes) lines.push(`  Availability: ${r.availabilityNotes}`);
  return lines.join('\n');
}

/** Compact list of every page, included in the system prompt so the model knows what exists. */
export function siteMap(): string {
  return pages.map((p) => `- ${p.path} — ${p.title}${p.description ? `: ${p.description}` : ''}`).join('\n');
}

export function isKnownPath(path: string): boolean {
  const clean = normalizePath(path);
  return pages.some((p) => p.path === clean);
}

function truncate(s: string, max: number): string {
  return s.length <= max ? s : `${s.slice(0, max)}\n[…truncated — use get_page for the full text]`;
}
